set -eu
Rscript --vanilla - "$(inputs.counts.path)" "$(inputs.gene_meta.path)" "$(inputs.sample_annot.path)" result.tsv <<'RS'
args <- commandArgs(trailingOnly = TRUE)
if (length(args) != 4L) stop("Expected counts, gene metadata, sample annotations, and output path")
counts_path <- args[[1]]
gene_meta_path <- args[[2]]
sample_annot_path <- args[[3]]
output_path <- args[[4]]

counts <- utils::read.csv(counts_path, check.names = FALSE, stringsAsFactors = FALSE)
gene_meta <- utils::read.csv(gene_meta_path, check.names = FALSE, stringsAsFactors = FALSE)
sample_annot <- utils::read.csv(sample_annot_path, check.names = FALSE, stringsAsFactors = FALSE)

if (ncol(counts) < 2L) stop("Expression matrix has no sample columns")
if (!all(c("Geneid", "Length", "gene_biotype") %in% names(gene_meta))) stop("Gene metadata lacks required columns")
if (!all(c("sample", "celltype") %in% names(sample_annot))) stop("Sample annotations lack required columns")
if (anyDuplicated(counts[[1]]) != 0L) stop("Expression gene identifiers are duplicated")
if (anyDuplicated(gene_meta$Geneid) != 0L) stop("Gene metadata identifiers are duplicated")
if (anyDuplicated(sample_annot$sample) != 0L) stop("Sample annotation identifiers are duplicated")
if (!setequal(names(counts)[-1], sample_annot$sample)) stop("Expression samples and annotations do not match exactly")

cell_types <- c("CD4", "CD8", "CD14", "CD19")
pc_rows <- which(gene_meta$gene_biotype == "protein_coding")
if (length(pc_rows) < 3L) stop("Fewer than three protein-coding genes")
count_rows <- match(gene_meta$Geneid[pc_rows], counts[[1]])
if (anyNA(count_rows)) stop("Some protein-coding genes are absent from expression matrix")
gene_length <- suppressWarnings(as.numeric(gene_meta$Length[pc_rows]))
if (anyNA(gene_length)) stop("Non-numeric gene length among protein-coding genes")

out <- lapply(cell_types, function(cell_type) {
  samples <- sample_annot$sample[sample_annot$celltype == cell_type]
  if (length(samples) < 2L) stop(paste("Insufficient samples for", cell_type))
  sample_cols <- match(samples, names(counts))
  if (anyNA(sample_cols)) stop(paste("Annotated sample missing from matrix for", cell_type))
  expr <- as.matrix(counts[count_rows, sample_cols, drop = FALSE])
  storage.mode(expr) <- "double"
  mean_expression <- base::rowMeans(expr, na.rm = FALSE)
  valid <- is.finite(gene_length) & is.finite(mean_expression)
  if (sum(valid) < 3L) stop(paste("Insufficient valid genes for", cell_type))
  r <- stats::cor(gene_length[valid], mean_expression[valid], method = "pearson")
  data.frame(
    cell_type = cell_type,
    n_samples = length(samples),
    n_genes = sum(valid),
    aggregation = "arithmetic_mean",
    expression_scale = "batch_corrected_read_counts_untransformed",
    gene_biotype = "protein_coding",
    method = "Pearson",
    pearson_r = r,
    abs_pearson_r = abs(r),
    stringsAsFactors = FALSE
  )
})
result <- do.call(rbind, out)
utils::write.table(result, file = output_path, sep = "	", quote = FALSE, row.names = FALSE, col.names = TRUE)
RS

